fn sign(x: Vec<i8>) -> Vec<i8> {
    // Map each element of x to its sign classification (-1, 0, 1)
    x.into_iter()
        .map(|v| {
            if v < 0 {
                -1
            } else if v == 0 {
                0
            } else {
                1
            }
        })
        .collect()
}